import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student("id-" + last, last, first, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Adler", "Sam")
        ]

    def test_sorted_and_chunked(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            [
                "Row 1: Adler, Sam | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row(self):
        rows = seating_rows(self.students, 10)
        self.assertEqual(len(rows), 1)

    def test_first_name_breaks_ties(self):
        pair = [
            make_student("Lee", "Zed"),
            make_student("Lee", "Amy")
        ]
        self.assertEqual(
            seating_rows(pair, 2),
            ["Row 1: Lee, Amy | Lee, Zed"]
        )

    def test_input_not_modified(self):
        before = list(self.students)
        seating_rows(self.students, 2)
        self.assertEqual(self.students, before)

    def test_bad_seat_counts(self):
        for count in (0, -3):
            with self.assertRaises(ValueError):
                seating_rows(self.students, count)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
